    static bool wait_for(const std::function<bool()>& done, std::chrono::milliseconds limit)
    {
        const auto until = std::chrono::steady_clock::now() + limit;
        if (done())
            return true;
        wxEventLoop loop;
        wxTimer     timer;
        bool        result = false;
        timer.Bind(wxEVT_TIMER, [&](wxTimerEvent&) {
            // Looked at between ticks, never during one: `done` may wait too.
            // A modal window's loop may be running inside this one, and Exit
            // from there never ends this loop, so wait until it has closed.
            if (wxEventLoopBase::GetActive() == &loop) {
                result = done();
                if (result || std::chrono::steady_clock::now() > until) {
                    loop.Exit();
                    return;
                }
            }
            timer.StartOnce(10);
        });
        timer.StartOnce(10);
        loop.Run();
        return result;
    }

    // What Home's printer rail shows for the named printer `name`, read through
